const s=require('../../../../miniprogram/utils/service'),d=require('../../../../miniprogram/utils/domain');Page({data:{busy:false,error:'',plans:[],selected:null,shopping:null},onShow(){this.load();},async load(){await s.run(this,async()=>{const c=await s.call();if(c.unbound)throw Error('请先加入家庭');this.state=c.state;this.setData({plans:Object.values(c.state.plans).sort((a,b)=>b.week.localeCompare(a.week)).map(p=>({...p,names:p.lines.map(l=>{const r=p.recipes.find(x=>x.id===l.id);return (r?r.name:l.id)+' × '+l.count;}).join('、')}))});});},onPullDownRefresh(){this.load().finally(()=>wx.stopPullDownRefresh());},open(e){const p=this.state.plans[e.currentTarget.dataset.week];this.setData({selected:p,shopping:d.shopping(this.state,p,p.supplies)});},close(){this.setData({selected:null});}});